import {annualBudgetDefinition,BUDGET_VERSION} from '../../assets/annual-position-budget-model.js';
import {annualBudgetFingerprint} from '../../lib/internal-annual-position-budget.js';
export const uid=n=>'00000000-0000-4000-8000-'+String(n).padStart(12,'0'),hash=c=>c.repeat(64);
export function definition(count=3){return annualBudgetDefinition({source:{instrument:'Ordenanza exclusivamente sintética QA',documentSha256:hash('d'),coverage:'annex_detail',reference:'Anexo inventado QA'},rows:Array.from({length:count},(_,i)=>({code:'QA'+String(i).padStart(4,'0'),jurisdiction:i%2?'02':'01',regime:null,group:null,section:null,subsection:null,position:null,label:'Cargo exclusivamente sintético '+i,unit:i===1?'teaching_hour':i===2?'contracted_staff':'position',quantity:i===0?'0':i===1?'12.50':'1',reference:'Fila inventada QA '+i}))});}
export function command(patch={}){return {command:'propose',year:2026,scopeVersion:hash('a'),baseVersion:hash('b'),proposalId:null,proposalSha256:null,definition:definition(),reason:'Propuesta exclusivamente sintética QA',reviewConfirmed:false,...patch};}
export function receipt(body=command(),patch={}){return {version:BUDGET_VERSION,eventId:uid(10),proposalId:uid(10),requestKey:uid(9),requestSha256:annualBudgetFingerprint(body),body,status:'pending',revision:0,catalogVersion:hash('b'),replayed:false,...patch};}
export function bootstrap({approved=false,count=3,year=2026}={}){const body=command({year,definition:definition(count)}),id=uid(10);return {version:BUDGET_VERSION,year,scopeVersion:hash('a'),catalog:{version:hash('b'),revision:approved?1:0,definition:approved?body.definition:null,definitionSha256:approved?annualBudgetFingerprint(body.definition):null,proposalId:approved?id:null,approvalId:approved?uid(11):null},proposals:approved?[{id,body,requestSha256:annualBudgetFingerprint(body),createdAt:'2026-10-01T12:00:00Z',authorLabel:'Preparador sintético QA',canReview:false,status:'approved',decision:{id:uid(11),command:'approve',reason:'Revisión exclusivamente sintética QA',actorLabel:'Revisor sintético QA',recordedAt:'2026-10-01T13:00:00Z',revision:1}}]:[],proposalCount:approved?1:0,complete:true,permissions:{canPropose:true,canReview:true}};}
